import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print('no')
        return

    n = int(data[0])

    if n == 0:
        print('yes')
        return

    if len(data) < n + 1:
        print('no')
        return

    arr = list(map(int, data[1:n+1]))

    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            print('no')
            return

    print('yes')

if __name__ == "__main__":
    main()
